function school(){const rows=arr('okulBilgileri');return rows.find(x=>x.id==='ayarlar')||rows[0]||{}}
function teachers(){return arr('ogretmenler')}
function adminNames(){const o=school(),ts=teachers(),mudur=ts.find(t=>t.id===o.mudurId)||ts.find(t=>(t.unvan||'').trim()==='Müdür'),yrd=ts.find(t=>(t.unvan||'').trim()==='Müdür Yardımcısı'),name=t=>t?`${t.ad||''} ${t.soyad||''}`.trim():'';return{mudur:name(mudur),yardimci:name(yrd)}}
function reportService(id){return arr('servisler').find(s=>s.id===id)||null}
function reportStudents(id){const classes=arr('siniflar');return arr('veliler').filter(v=>v.servisId===id).map(v=>({id:v.id,ad:v.ogrenciAdi||'',sinif:classes.find(s=>s.id===v.sinifId)?.ad||v.sinifAdi||''})).sort((a,b)=>a.ad.localeCompare(b.ad,'tr'))}
function schoolTitle(){const o=school(),parts=[];if(o.il)parts.push(`${String(o.il).toLocaleUpperCase('tr')} İLİ`);if(o.ilce)parts.push(`${String(o.ilce).toLocaleUpperCase('tr')} İLÇESİ`);parts.push(String(o.okulAdi||'KORUK İLK-ORTAOKULU').toLocaleUpperCase('tr'));return parts.join(' ')}
async function prepareReports(){if(!global.SyncEngine||!global.COL)return;const defs={okulBilgileri:COL.okulBilgileri,resmiTatiller:COL.resmiTatiller},types=[];for(const[t,c]of Object.entries(defs)){if(c){SyncEngine.register(t,c);types.push(t)}}if(types.length){await SyncEngine.localHydrate(types);SyncEngine.schedule(60)}}
function signatures(){const a=adminNames();return `<table><tbody><tr><td><strong>${escReport(a.yardimci)}</strong><br>Müdür Yardımcısı</td><td><strong>${escReport(a.mudur)}</strong><br>Okul Müdürü</td></tr></tbody></table>`}
async function denetim(servisId){await prepareReports();const s=reportService(servisId);if(!s)throw new Error('servis-bulunamadi');const count=reportStudents(servisId).length,rows=DENETIM.map(([m,r],i)=>`<tr><td>${i+1}. ${escReport(m)}<br><small>(${escReport(r)})</small></td><td></td><td></td><td></td></tr>`).join(''),body=`<h1>${escReport(schoolTitle())}</h1><h2>OKUL SERVİS ARACI DENETİM FORMU</h2><table><tbody><tr><th>Servis</th><td>${escReport(s.servisAdi||s.guzergah||'')}</td><th>Plaka</th><td>${escReport(s.plaka||'')}</td></tr><tr><th>Sürücü</th><td>${escReport(s.soforAdi||'')}</td><th>Telefon</th><td>${escReport(s.soforTelefon||'')}</td></tr><tr><th>Öğrenci Sayısı</th><td>${count}</td><th>Tarih</th><td>${new Date().toLocaleDateString('tr-TR')}</td></tr></tbody></table><table><thead><tr><th>DENETLEME KONULARI</th><th>EVET</th><th>HAYIR</th><th>AÇIKLAMALAR</th></tr></thead><tbody>${rows}</tbody></table>${signatures()}`;return ReportEngine.printReport('Okul Servis Aracı Denetim Formu',body,{fileName:`${s.plaka||'Servis'}_Denetim`,yon:'dikey'})}
function holiday(iso){const t=arr('resmiTatiller').find(x=>x.tarih===iso);return t?(t.aciklama||t.ad||'Resmî Tatil'):null}
function dateIso(y,m,d){return`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function studentTable(list){const rows=[...list];while(rows.length<30)rows.push({ad:'',sinif:''});return `<table><thead><tr><th>Sıra</th><th>Öğrenci Adı Soyadı</th><th>Sınıf</th></tr></thead><tbody>${rows.map((o,i)=>`<tr><td>${i+1}</td><td>${escReport(o.ad)}</td><td>${escReport(o.sinif)}</td></tr>`).join('')}</tbody></table>`}
function dailyRows(y,m){const last=new Date(y,m+1,0).getDate();let out='';for(let d=1;d<=last;d++){const dt=new Date(y,m,d),weekend=dt.getDay()===0||dt.getDay()===6,iso=dateIso(y,m,d),h=!weekend&&holiday(iso),label=`${d} ${AYLAR[m]} ${y} ${GUNLER[dt.getDay()]}`,mark=weekend?'Hafta Sonu':h?'Resmî Tatil':'';out+=`<tr><td>${escReport(label)}</td>${mark?`<td colspan="8">${escReport(mark)}</td>`:'<td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td>'}</tr>`}return out}
async function takip(servisId,yil=new Date().getFullYear(),ay=new Date().getMonth()){await prepareReports();const s=reportService(servisId);if(!s)throw new Error('servis-bulunamadi');const ayAdi=`${AYLAR[ay].toLocaleUpperCase('tr')} - ${yil}`,body=`<h1>${escReport(schoolTitle())}</h1><h2>${escReport(ayAdi)} TAŞIMA TAKİP ÇİZELGESİ</h2><table><tbody><tr><th>Servis</th><td>${escReport(s.servisAdi||s.guzergah||'')}</td><th>Sürücü</th><td>${escReport(s.soforAdi||'')}</td></tr><tr><th>Plaka</th><td>${escReport(s.plaka||'')}</td><th>Telefon</th><td>${escReport(s.soforTelefon||'')}</td></tr></tbody></table>${studentTable(reportStudents(servisId))}<table><thead><tr><th rowspan="2">Tarih</th><th colspan="4">Öğle</th><th colspan="4">Akşam</th></tr><tr><th>Geliş Saati</th><th>Gelen Sayı</th><th>Şoför İmza</th><th>N. Öğrt. İmza</th><th>Çıkış Saati</th><th>Giden Sayı</th><th>Şoför İmza</th><th>N. Öğrt. İmza</th></tr></thead><tbody>${dailyRows(yil,ay)}</tbody></table>${signatures()}`;return ReportEngine.printReport(`${ayAdi} Taşıma Takip Çizelgesi`,body,{fileName:`${s.plaka||'Servis'}_${AYLAR[ay]}_${yil}_Takip`,yon:'dikey'})}
function takipSec(servisId){const now=new Date(),ov=document.createElement('div');ov.id='transportReportPicker';ov.className='ka-modal-backdrop';ov.innerHTML=`<section class="ka-modal"><div class="ka-modal__header"><strong>Aylık Taşıma Takip Çizelgesi</strong><button class="ka-btn ka-btn--secondary ka-btn--sm" data-close type="button">Kapat</button></div><div class="ka-modal__body ka-grid"><label class="ka-field"><span class="ka-field__label">Yıl</span><input id="trYear" type="number" min="2020" max="2100" value="${now.getFullYear()}"></label><label class="ka-field"><span class="ka-field__label">Ay</span><select id="trMonth">${AYLAR.map((a,i)=>`<option value="${i}" ${i===now.getMonth()?'selected':''}>${a}</option>`).join('')}</select></label></div><div class="ka-modal__footer"><button class="ka-btn" data-print type="button">Yazdır / PDF</button></div></section>`;document.body.appendChild(ov);ov.querySelector('[data-close]').onclick=()=>ov.remove();ov.querySelector('[data-print]').onclick=async()=>{const b=ov.querySelector('[data-print]');b.disabled=true;try{await takip(servisId,Number(ov.querySelector('#trYear').value),Number(ov.querySelector('#trMonth').value));ov.remove()}catch(e){toast?.('Rapor hazırlanamadı: '+(e?.message||e));b.disabled=false}}}
